// Factory function demonstrating closures and private variable state
function createBankAccount(accountHolder, initialDeposit) {
  // Private variables confined to this function execution context
  let balance = initialDeposit;
  const transactionHistory = [
    { type: 'INITIAL_DEPOSIT', amount: initialDeposit, date: new Date().toISOString() }
  ];

  // Return public API object with closures retaining access to private state
  return {
    getHolderName() {
      return accountHolder;
    },

    getBalance() {
      return balance;
    },

    deposit(amount) {
      if (typeof amount !== 'number' || amount <= 0) {
        throw new Error('Deposit amount must be a positive number.');
      }
      balance += amount;
      transactionHistory.push({ type: 'DEPOSIT', amount, date: new Date().toISOString() });
      return balance;
    },

    withdraw(amount) {
      if (amount > balance) {
        throw new Error('Insufficient funds.');
      }
      balance -= amount;
      transactionHistory.push({ type: 'WITHDRAWAL', amount, date: new Date().toISOString() });
      return balance;
    },

    getStatement() {
      // Return a shallow copy of transactions to preserve encapsulation
      return [...transactionHistory];
    }
  };
}

