// Complete Event Delegation and LocalStorage Controller
class TodoApp {
  constructor() {
    this.storageKey = 'arshith_todos_v1';
    this.todos = this.loadFromStorage();
    this.form = document.getElementById('todo-form');
    this.input = document.getElementById('todo-input');
    this.list = document.getElementById('todo-list');

    this.bindEvents();
    this.render();
  }

  loadFromStorage() {
    try {
      const data = localStorage.getItem(this.storageKey);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      console.error('LocalStorage read error:', e);
      return [];
    }
  }

  saveToStorage() {
    localStorage.setItem(this.storageKey, JSON.stringify(this.todos));
  }

  bindEvents() {
    // 1. Form Submission
    this.form.addEventListener('submit', (e) => {
      e.preventDefault();
      const text = this.input.value.trim();
      if (!text) return;

      this.todos.unshift({
        id: Date.now().toString(),
        text,
        completed: false
      });

      this.saveToStorage();
      this.input.value = '';
      this.render();
    });

    // 2. Event Delegation on Parent Container
    this.list.addEventListener('click', (e) => {
      const target = e.target;
      const li = target.closest('li[data-id]');
      if (!li) return;
      const todoId = li.dataset.id;

      // Handle Delete Button Click
      if (target.classList.contains('btn-delete')) {
        this.todos = this.todos.filter(t => t.id !== todoId);
        this.saveToStorage();
        this.render();
      }

      // Handle Checkbox Toggle
      if (target.classList.contains('toggle-check')) {
        const item = this.todos.find(t => t.id === todoId);
        if (item) {
          item.completed = !item.completed;
          this.saveToStorage();
          this.render();
        }
      }
    });
  }

  render() {
    // Utilize DocumentFragment to perform atomic single-reflow DOM mount
    const fragment = document.createDocumentFragment();

    this.todos.forEach(todo => {
      const li = document.createElement('li');
      li.dataset.id = todo.id;
      li.className = `todo-item ${todo.completed ? 'completed' : ''}`;

      li.innerHTML = `
        <input type="checkbox" class="toggle-check" ${todo.completed ? 'checked' : ''}>
        <span class="todo-text">${this.escapeHTML(todo.text)}</span>
        <button class="btn-delete" aria-label="Delete task">×</button>
      `;

      fragment.appendChild(li);
    });

    this.list.innerHTML = '';
    this.list.appendChild(fragment);
  }

  escapeHTML(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }
}

