// Resilient Async API Client with Timeout and Error Boundary
async function fetchWithTimeout(url, options = {}, timeoutMs = 5000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(url, {
      ...options,
      signal: controller.signal,
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        ...options.headers
      }
    });

    // Check HTTP status code (fetch does NOT reject on 4xx/5xx!)
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.message || `HTTP Error ${response.status}: ${response.statusText}`);
    }

    const data = await response.json();
    return { success: true, data };
  } catch (error) {
    if (error.name === 'AbortError') {
      console.error(`Request to ${url} timed out after ${timeoutMs}ms.`);
      return { success: false, error: 'Network request timed out. Please check your connection.' };
    }
    console.error('API Request failed:', error.message);
    return { success: false, error: error.message };
  } finally {
    clearTimeout(timer); // Clean up timer memory
  }
}

// Verification Call
fetchWithTimeout('http://localhost:5000/api/courses/web-development')
  .then(res => console.log('API Client Result:', res));

