// 3. Dynamic Course Detail Component with useParams & useEffect
function CourseDetailPage() {
  const { courseId } = useParams();
  const navigate = useNavigate();
  const [course, setCourse] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const controller = new AbortController();

    async function fetchCourse() {
      try {
        setLoading(true);
        const res = await fetch(`http://localhost:5000/api/courses/${courseId}`, {
          signal: controller.signal
        });
        const data = await res.json();
        if (data.success) {
          setCourse(data.course);
        }
      } catch (err) {
        if (err.name !== 'AbortError') console.error(err);
      } finally {
        setLoading(false);
      }
    }

    fetchCourse();
    return () => controller.abort(); // Cleanup aborts hanging fetch
  }, [courseId]);

  if (loading) return <div className="loader">Loading course details...</div>;
  if (!course) return <div>Course not found. <button onClick={() => navigate('/courses')}>Back</button></div>;

  return (
    <div className="course-detail">
      <h1>{course.title}</h1>
      <p>{course.description}</p>
      <button onClick={() => navigate('/courses')}>← Back to Catalog</button>
    </div>
  );
}

