// server.js - Production-Ready Express REST Server
const express = require('express');
const cors = require('cors');

const app = express();
const PORT = process.env.PORT || 5000;

// ==========================================
// 1. Global Middleware Pipeline
// ==========================================
app.use(cors({ origin: 'http://localhost:3000' }));
app.use(express.json()); // Parses application/json into req.body

// Custom Request Logger Middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);
  next(); // Pass control to next handler
});

// ==========================================
// 2. In-Memory Data Store & Route Handlers
// ==========================================
let courses = [
  { id: 'web-dev', title: 'Web Development', category: 'Programming', modulesCount: 15 },
  { id: 'python', title: 'Python Programming', category: 'Programming', modulesCount: 15 }
];

// GET /api/courses - List courses with search query
app.get('/api/courses', (req, res) => {
  const { search } = req.query;
  let results = courses;
  if (search) {
    const q = search.toLowerCase();
    results = results.filter(c => c.title.toLowerCase().includes(q));
  }
  res.json({ success: true, count: results.length, data: results });
});

// GET /api/courses/:id - Single Course Lookup
app.get('/api/courses/:id', (req, res, next) => {
  const course = courses.find(c => c.id === req.params.id);
  if (!course) {
    const error = new Error(`Course with ID '${req.params.id}' not found.`);
    error.status = 404;
    return next(error); // Forward to error handler
  }
  res.json({ success: true, data: course });
});

// POST /api/courses - Create Course with Validation
app.post('/api/courses', (req, res, next) => {
  const { title, category, modulesCount } = req.body;

  if (!title || !category) {
    const error = new Error('Course title and category are required.');
    error.status = 400;
    return next(error);
  }

  const newCourse = {
    id: title.toLowerCase().replace(/\s+/g, '-'),
    title,
    category,
    modulesCount: Number(modulesCount) || 1
  };

  courses.push(newCourse);
  res.status(201).json({ success: true, message: 'Course created successfully', data: newCourse });
});

// ==========================================
// 3. Centralized Error-Handling Middleware
// ==========================================
app.use((err, req, res, next) => {
  const statusCode = err.status || 500;
  console.error(`[Error ${statusCode}] ${err.message}`);
  res.status(statusCode).json({
    success: false,
    message: err.message || 'Internal Server Error'
  });
});

app.listen(PORT, () => {
  console.log(`Express API server listening on port ${PORT}`);
});

