// Lazily loaded components split into separate on-demand chunks
const LearningPage = lazy(() => import('./pages/LearningPage'));
const AdminDashboard = lazy(() => import('./pages/AdminDashboard'));
const FinalExamPage = lazy(() => import('./pages/FinalExamPage'));

// Fallback loader component displayed while chunk downloads
function PageLoader() {
  return (
    <div className="page-loader" role="status" aria-live="polite">
      <div className="spinner"></div>
      <p>Loading application module...</p>
    </div>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      {/* Suspense catches lazy loading promises across all routes */}
      <Suspense fallback={<PageLoader />}>
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route path="/courses" element={<CatalogPage />} />
          <Route path="/learn/:courseId/:moduleId" element={<LearningPage />} />
          <Route path="/admin" element={<AdminDashboard />} />
          <Route path="/exam/:courseId" element={<FinalExamPage />} />
          <Route path="*" element={<div>Page not found. <Link to="/">Return Home</Link></div>} />
        </Routes>
      </Suspense>
    </BrowserRouter>
  );
}

