// Project 2: Interactive Task Dashboard
// app.js - Vanilla JS State Engine & DOM Controller

class TaskManager {
  constructor(storageKey = 'arshith_tasks_v1') {
    this.storageKey = storageKey;
    this.tasks = this.loadTasks();
    this.currentFilter = 'all';
    this.searchQuery = '';
    this.initElements();
    this.bindEvents();
    this.render();
  }

  loadTasks() {
    try {
      const data = localStorage.getItem(this.storageKey);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      console.error('Failed to load tasks from localStorage', e);
      return [];
    }
  }

  saveTasks() {
    localStorage.setItem(this.storageKey, JSON.stringify(this.tasks));
  }

  initElements() {
    this.form = document.getElementById('task-form');
    this.input = document.getElementById('task-input');
    this.categorySelect = document.getElementById('task-category');
    this.taskList = document.getElementById('task-list');
    this.itemsLeftCount = document.getElementById('items-left');
    this.filterButtons = document.querySelectorAll('.filter-btn');
    this.searchInput = document.getElementById('search-input');
    this.clearCompletedBtn = document.getElementById('clear-completed');
  }

  bindEvents() {
    this.form.addEventListener('submit', (e) => {
      e.preventDefault();
      this.addTask(this.input.value.trim(), this.categorySelect.value);
    });

    this.taskList.addEventListener('click', (e) => {
      const target = e.target;
      const li = target.closest('li[data-id]');
      if (!li) return;
      const taskId = li.dataset.id;

      if (target.classList.contains('toggle-check')) {
        this.toggleTask(taskId);
      } else if (target.classList.contains('btn-delete')) {
        this.deleteTask(taskId);
      }
    });

    this.filterButtons.forEach(btn => {
      btn.addEventListener('click', (e) => {
        this.filterButtons.forEach(b => b.classList.remove('active'));
        e.target.classList.add('active');
        this.currentFilter = e.target.dataset.filter;
        this.render();
      });
    });

    if (this.searchInput) {
      this.searchInput.addEventListener('input', (e) => {
        this.searchQuery = e.target.value.toLowerCase();
        this.render();
      });
    }

    if (this.clearCompletedBtn) {
      this.clearCompletedBtn.addEventListener('click', () => {
        this.tasks = this.tasks.filter(t => !t.completed);
        this.saveTasks();
        this.render();
      });
    }
  }

  addTask(title, category = 'General') {
    if (!title) return;
    const newTask = {
      id: Date.now().toString(),
      title: title,
      category: category,
      completed: false,
      createdAt: new Date().toISOString()
    };
    this.tasks.unshift(newTask);
    this.saveTasks();
    this.input.value = '';
    this.render();
  }

  toggleTask(id) {
    const task = this.tasks.find(t => t.id === id);
    if (task) {
      task.completed = !task.completed;
      this.saveTasks();
      this.render();
    }
  }

  deleteTask(id) {
    this.tasks = this.tasks.filter(t => t.id !== id);
    this.saveTasks();
    this.render();
  }

  getFilteredTasks() {
    return this.tasks.filter(task => {
      const matchesSearch = task.title.toLowerCase().includes(this.searchQuery);
      let matchesFilter = true;
      if (this.currentFilter === 'active') matchesFilter = !task.completed;
      if (this.currentFilter === 'completed') matchesFilter = task.completed;
      return matchesSearch && matchesFilter;
    });
  }

  render() {
    const filtered = this.getFilteredTasks();
    this.taskList.innerHTML = '';

    if (filtered.length === 0) {
      this.taskList.innerHTML = '<li class="empty-state">No matching tasks found.</li>';
    } else {
      filtered.forEach(task => {
        const li = document.createElement('li');
        li.dataset.id = task.id;
        li.className = `task-item ${task.completed ? 'completed' : ''}`;
        li.innerHTML = `
          <input type="checkbox" class="toggle-check" ${task.completed ? 'checked' : ''}>
          <span class="task-text">${this.escapeHtml(task.title)}</span>
          <span class="task-badge">${task.category}</span>
          <button class="btn-delete" aria-label="Delete task">×</button>
        `;
        this.taskList.appendChild(li);
      });
    }

    const activeCount = this.tasks.filter(t => !t.completed).length;
    if (this.itemsLeftCount) {
      this.itemsLeftCount.textContent = `${activeCount} item${activeCount !== 1 ? 's' : ''} left`;
    }
  }

  escapeHtml(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }
}

