// Project 3: Full-Stack Course Catalog REST API
// server.js - Express Backend

const express = require('express');
const cors = require('cors');

const app = express();
const PORT = process.env.PORT || 5000;

app.use(cors());
app.use(express.json());

// In-Memory Database Store
let courses = [
  { id: '1', title: 'Python Programming Masterclass', category: 'Programming', level: 'Beginner', duration: '40 Hours' },
  { id: '2', title: 'SQL & Relational Databases', category: 'Database', level: 'Intermediate', duration: '30 Hours' },
  { id: '3', title: 'Modern Full-Stack Web Development', category: 'Web Development', level: 'Beginner to Advanced', duration: '60 Hours' }
];

// Validation Middleware
const validateCourse = (req, res, next) => {
  const { title, category, level, duration } = req.body;
  if (!title || !category || !level || !duration) {
    return res.status(400).json({
      success: false,
      message: 'All fields (title, category, level, duration) are required.'
    });
  }
  next();
};

// GET /api/courses - List all courses with optional search
app.get('/api/courses', (req, res) => {
  const { search } = req.query;
  let results = courses;
  if (search) {
    const q = search.toLowerCase();
    results = results.filter(c => c.title.toLowerCase().includes(q) || c.category.toLowerCase().includes(q));
  }
  res.json({ success: true, count: results.length, data: results });
});

// GET /api/courses/:id - Get single course
app.get('/api/courses/:id', (req, res) => {
  const course = courses.find(c => c.id === req.params.id);
  if (!course) {
    return res.status(404).json({ success: false, message: 'Course not found' });
  }
  res.json({ success: true, data: course });
});

// POST /api/courses - Create new course
app.post('/api/courses', validateCourse, (req, res) => {
  const { title, category, level, duration } = req.body;
  const newCourse = {
    id: Date.now().toString(),
    title,
    category,
    level,
    duration
  };
  courses.push(newCourse);
  res.status(201).json({ success: true, message: 'Course created successfully', data: newCourse });
});

// DELETE /api/courses/:id - Delete a course
app.delete('/api/courses/:id', (req, res) => {
  const initialLength = courses.length;
  courses = courses.filter(c => c.id !== req.params.id);
  if (courses.length === initialLength) {
    return res.status(404).json({ success: false, message: 'Course not found' });
  }
  res.json({ success: true, message: 'Course deleted successfully' });
});

app.listen(PORT, () => {
  console.log(`Course API server running on port ${PORT}`);
});

