def sanitize_user_records(records: list) -> tuple:
    clean_records = []
    error_count = 0

    for r in records:
        try:
            uid = str(r['user_id']).strip()
            age = float(r['age'])
            income = float(r['income'])

            if age < 0 or income < 0:
                error_count += 1
                continue

            clean_records.append({
                'user_id': uid,
                'age': age,
                'income': income
            })
        except (KeyError, ValueError, TypeError):
            error_count += 1

    return clean_records, error_count

# Verification
raw_test = [
    {'user_id': 'U101', 'age': '28', 'income': '75000'},
    {'user_id': 'U102', 'age': -5, 'income': '50000'},
    {'user_id': 'U103', 'age': 'unknown', 'income': '100000'},
    {'user_id': 'U104', 'age': 42, 'income': 120000.50}
]
clean, errs = sanitize_user_records(raw_test)
print(f"Clean Records: {len(clean)}, Errors Logged: {errs}")

