import pandas as pd
import numpy as np

def audit_feature_distributions(df, threshold_skew=1.0):
    report = []
    numeric_cols = df.select_dtypes(include=[np.number]).columns

    for col in numeric_cols:
        skew = df[col].skew()
        min_val = df[col].min()

        recommendation = "None (Sufficiently Symmetric)"
        if skew > threshold_skew:
            if min_val > 0:
                recommendation = "Box-Cox or Log Transform (np.log)"
            elif min_val == 0:
                recommendation = "Log1p Transform (np.log1p)"
            else:
                recommendation = "Yeo-Johnson Transform"
        elif skew < -threshold_skew:
            recommendation = "Reflect + Log or Yeo-Johnson Transform"

        report.append({
            "feature": col,
            "skewness": round(skew, 3),
            "min_value": min_val,
            "recommended_transform": recommendation
        })

    return pd.DataFrame(report)

# Demonstration
sample_data = pd.DataFrame({
    "normal_feat": np.random.normal(50, 10, 500),
    "skewed_sales": np.random.exponential(scale=20, size=500),
    "skewed_with_zeros": np.random.choice([0, 1, 5, 25, 100, 500], size=500)
})
print(audit_feature_distributions(sample_data))

